param([string]$DataRoot,[switch]$Stop,[int]$Port=0)
$ErrorActionPreference='Stop'
$package=Split-Path -Parent $PSScriptRoot
$identity=Get-Content -LiteralPath (Join-Path $package 'BUILD_IDENTITY.json') -Raw|ConvertFrom-Json
if(!$DataRoot){$DataRoot=Join-Path $env:LOCALAPPDATA ('KitaoDiagnostic/OnlineHttpV1-'+$identity.productSourceSha.Substring(0,8))}
if(![IO.Path]::IsPathRooted($DataRoot)){throw 'Use an absolute isolated data root'}
$DataRoot=[IO.Path]::GetFullPath($DataRoot);$connection=Join-Path $DataRoot 'PRIVATE_CONNECTION.json';$service=Join-Path $package 'selection-service/PixelTart.SelectionApi.Server.exe'
if(!(Test-Path -LiteralPath $service)){throw 'LocalDev service is missing from this test bundle'}
function WriteConnection($c){$c|ConvertTo-Json -Depth 5|Set-Content -LiteralPath $connection -Encoding UTF8}
if(Test-Path -LiteralPath $connection){$config=Get-Content -LiteralPath $connection -Raw|ConvertFrom-Json}else{if($Stop){throw 'No owned service receipt'};New-Item -ItemType Directory $DataRoot -Force|Out-Null;$bytes=New-Object byte[] 32;$rng=[Security.Cryptography.RandomNumberGenerator]::Create();$rng.GetBytes($bytes);$rng.Dispose();if(!$Port){$socket=[Net.Sockets.TcpListener]::new([Net.IPAddress]::Loopback,0);$socket.Start();$Port=$socket.LocalEndpoint.Port;$socket.Stop()};$config=[pscustomobject]@{endpoint="http://127.0.0.1:$Port/";ownerKey=[BitConverter]::ToString($bytes).Replace('-','');port=$Port;root=(Join-Path $DataRoot 'service-state');pid=0;startedUtc='';instanceId=''};WriteConnection $config}
if($Stop){$p=Get-Process -Id $config.pid -ErrorAction SilentlyContinue;if(!$p){Write-Output 'Owned test service is already stopped.';return};if($p.Path -ine $service -or $p.StartTime.ToUniversalTime().ToString('o') -cne $config.startedUtc){throw 'PID no longer matches this owned service; nothing stopped'};Stop-Process -Id $p.Id;Write-Output 'Owned LocalDev service stopped; test data retained.';return}
$ready=$null;try{$ready=Invoke-RestMethod -Uri ($config.endpoint+'health/ready') -TimeoutSec 2}catch{}
if($ready){if($ready.mode -ne 'LocalDevHttpV1' -or !$config.instanceId -or $ready.instanceId -ne $config.instanceId){throw 'The configured port belongs to another service; it was not reused or stopped'}}else{
 $keys=@('PIXELTART_SELECTION_LOCALDEV_ROOT','PIXELTART_SELECTION_LOCALDEV_PORT','PIXELTART_SELECTION_OWNER_KEY');$saved=@{};foreach($k in $keys){$saved[$k]=[Environment]::GetEnvironmentVariable($k,'Process')}
 try{[Environment]::SetEnvironmentVariable($keys[0],$config.root,'Process');[Environment]::SetEnvironmentVariable($keys[1],[string]$config.port,'Process');[Environment]::SetEnvironmentVariable($keys[2],$config.ownerKey,'Process');$log=Join-Path $DataRoot ('service-'+[DateTime]::UtcNow.ToString('yyyyMMddHHmmssfff'));$p=Start-Process -FilePath $service -WorkingDirectory (Split-Path $service) -WindowStyle Hidden -RedirectStandardOutput ($log+'.stdout.log') -RedirectStandardError ($log+'.stderr.log') -PassThru;$config.pid=$p.Id;$config.startedUtc=$p.StartTime.ToUniversalTime().ToString('o');WriteConnection $config}finally{foreach($k in $keys){[Environment]::SetEnvironmentVariable($k,$saved[$k],'Process')}}
 $until=[DateTime]::UtcNow.AddSeconds(30);do{try{$ready=Invoke-RestMethod -Uri ($config.endpoint+'health/ready') -TimeoutSec 1}catch{};if(!$ready){Start-Sleep -Milliseconds 100}}until($ready -or [DateTime]::UtcNow -gt $until)
 if(!$ready -or $ready.mode -ne 'LocalDevHttpV1'){throw 'LocalDev service did not become ready; see isolated service logs'};$instance=Get-Content -LiteralPath (Join-Path $config.root 'service-instance.id') -Raw;if($instance.Trim() -ne $ready.instanceId){throw 'Health response does not bind this service root'};$config.instanceId=$ready.instanceId;WriteConnection $config
}
$sampleDirectory=Join-Path $DataRoot 'test-assets';New-Item -ItemType Directory $sampleDirectory -Force|Out-Null;$sample=Join-Path $sampleDirectory 'synthetic-network.jpg'
if(!(Test-Path -LiteralPath $sample)){Add-Type -AssemblyName System.Drawing;$bitmap=New-Object System.Drawing.Bitmap 160,120;$graphics=[Drawing.Graphics]::FromImage($bitmap);try{$graphics.Clear([Drawing.Color]::FromArgb(225,145,50));$bitmap.Save($sample,[Drawing.Imaging.ImageFormat]::Jpeg)}finally{$graphics.Dispose();$bitmap.Dispose()}}
Write-Output ('Synthetic test JPEG: '+$sample)
$exe=Join-Path $package 'app/KitaoPhotoSelector.exe';$si=[Diagnostics.ProcessStartInfo]::new();$si.FileName=$exe;$si.WorkingDirectory=Split-Path $exe;$si.UseShellExecute=$false;$si.EnvironmentVariables['PIXEL_TART_ISOLATED_RUNTIME']='1';$si.EnvironmentVariables['PIXEL_TART_ISOLATED_RUNTIME_ROOT']=Join-Path $DataRoot 'desktop';$si.EnvironmentVariables['PIXELTART_SELECTION_ENDPOINT']=$config.endpoint;$si.EnvironmentVariables['PIXELTART_SELECTION_OWNER_KEY']=$config.ownerKey
$app=[Diagnostics.Process]::Start($si);Write-Output ('LocalDev endpoint: '+$config.endpoint);Write-Output ('Private data root: '+$DataRoot);Write-Output ('Desktop PID: '+$app.Id)
